        push('passend', [], 'End of pass ' + pass + ' \u2014 distances improved this pass: ' + impPass);
      }
      self.postMessage({ ok: true, frames: frames, final: snap() });
    } catch (err) {
      var m = String(err && err.message ? err.message : err);
