    }
  };
}

/* ─────────── run / replay ─────────── */
var frames = [], idx = 0, badEdges = [], badVerts = [], worker = null, playTimer = null, fps = 6;

function parseOrder(src) {
  var re = /\(\s*([A-Za-z_]\w*)\s*,\s*([A-Za-z_]\w*)\s*,\s*(-?\d+(?:\.\d+)?)\s*\)/g, m, out = [];
  while ((m = re.exec(src))) {
    if (VERTS.indexOf(m[1]) < 0 || VERTS.indexOf(m[2]) < 0)
      throw new Error('unknown vertex in (' + m[1] + ',' + m[2] + ') — use s, t, x, y, z');
    out.push({ u: m[1], v: m[2], w: parseFloat(m[3]) });
  }
  if (!out.length) throw new Error('no edges parsed — expected entries like (t,x,5)');
  return out;
}
function setStatus(kind, txt) {
  var el = document.getElementById('runStatus');
  el.textContent = txt;
  el.style.color = (kind === 'ok') ? '#177a2e' : (kind === 'err') ? '#c00000' : (kind === 'warn') ? '#a35400' : '#555';
}
function loadCode(which) {
  document.getElementById('relaxEditorCode').value = CODES[which];
  ['sample', 'buggy', 'starter'].forEach(function (k) {
    var b = document.getElementById('tabBtn_' + k); if (b) b.className = (k === which) ? 'active' : '';
  });
}
function trigger_run() {
