  catch (e) { setStatus('err', '\u2716 Edge list: ' + e.message); return; }
  orderEdges = edges; rebuildOrderList(edges);
  var code = document.getElementById('relaxEditorCode').value;
  setStatus('run', 'running\u2026');
  var btn = document.getElementById('runBtn'); btn.disabled = true;
  if (worker) { worker.terminate(); worker = null; }
  var url = URL.createObjectURL(new Blob(['(' + bfWorkerBody.toString() + ')()'], { type: 'text/javascript' }));
  var done = false;
  function cleanup() { if (worker) { worker.terminate(); worker = null; } URL.revokeObjectURL(url); btn.disabled = false; }
  worker = new Worker(url);
  var timer = setTimeout(function () {
    if (done) return; done = true; cleanup();
    finishRun({ ok: false, frames: [], error: 'Timed out after 1.5 s \u2014 infinite loop in relax()?' });
  }, 1500);
  worker.onmessage = function (ev) { if (done) return; done = true; clearTimeout(timer); cleanup(); finishRun(ev.data); };
  worker.onerror = function (ev) {
    if (done) return; done = true; clearTimeout(timer); cleanup();
    finishRun({ ok: false, frames: [], error: 'Worker error: ' + (ev.message || 'unknown') });
  };
  worker.postMessage({ code: code, edges: edges, verts: VERTS, passes: 4, source: 's' });
}
function checkRun(final) {
