    sp.style.cssText = 'display:inline-block;padding:1px 4px;margin:1px;border-radius:3px;' +
      'background:#f0f0f0;color:#555;font-family:ui-monospace,Consolas,monospace;font-size:11px';
    host.appendChild(sp);
    orderItems.push(sp);
  });
}

/* ─────────── rendering ─────────── */
var treeOn = true;
var lastView = null;

function renderView(v) {
  lastView = v;
  VERTS.forEach(function (k) {
    setText(nodeVal[k], fmtd(v.dist[k]));
    nodeCircle[k].fill(v.upd === k ? '#ffd08a' : NODE_FILL);
    var isBad = v.badVerts && v.badVerts.indexOf(k) >= 0;
    nodeCircle[k].stroke({ color: isBad ? '#d02020' : '#000', width: isBad ? 2.8 : 1.7 });
  });
  EDGES.forEach(function (e) {
    var isTree = treeOn && v.pred && v.pred[e.v] === e.u;
    e.tree.opacity(isTree ? 1 : 0);
    var isCur = v.cur && v.cur[0] === e.u && v.cur[1] === e.v;
    e.hi.opacity(isCur ? 1 : 0);
    e.badEl.opacity((v.bad && v.bad.indexOf(e.key) >= 0) ? 1 : 0);
  });
  if (v.cur && v.tent !== null && v.tent !== undefined) {
    var ce = null;
    EDGES.forEach(function (e) { if (e.u === v.cur[0] && e.v === v.cur[1]) ce = e; });
    if (ce) {
      setText(tentLbl, 'd[' + ce.u + ']+w = ' + fmtd(v.tent));
      tentLbl.attr({ x: Math.min(450, Math.max(70, ce.mid[0])), y: ce.mid[1] - 17 });
      tentLbl.opacity(1);
    } else { tentLbl.opacity(0); }
  } else { tentLbl.opacity(0); }

  setText(capMain, v.caption || '');
  capMain.font({ size: v.capSize || 26 });

  var imp = document.getElementById('impRead');
  if (imp) imp.textContent = 'distances improved this pass: ' + (v.imp === undefined || v.imp === null ? 0 : v.imp);
  var nr = document.getElementById('noteRead');
  if (nr) nr.textContent = v.note || '';
  orderItems.forEach(function (sp, i) {
    var on = (v.edgeIdx === i);
    sp.style.background = on ? '#ffd9b0' : '#f0f0f0';
    sp.style.color = on ? '#a35400' : '#555';
    sp.style.fontWeight = on ? '700' : '400';
  });
}

/* ─────────── snapshot mode ─────────── */
var mode = 'snapshot', curSnap = 'init';
function setActiveSnap(name) {
  ['init', 'pass1', 'pass2', 'pass3', 'pass4'].forEach(function (k) {
    var b = document.getElementById('snapBtn_' + k);
    if (b) b.className = (k === name) ? 'active' : '';
  });
}
function setSnapshot(name) {
  stopPlay();
  mode = 'snapshot'; curSnap = name;
  setActiveSnap(name);
  var s = SNAPS[name];
  renderView({ dist: s.dist, pred: s.pred, caption: PANEL[name], capSize: 26, imp: s.imp, note: s.note,
               cur: null, tent: null, edgeIdx: -1, bad: [], badVerts: [] });
  document.getElementById('frameCaption').textContent = PANEL[name] + ' ' + s.note;
}
function toggle_showTree(on) {
  treeOn = on;
  if (mode === 'snapshot') setSnapshot(curSnap); else showFrame(idx);
}

/* ─────────── worker: student relax() ─────────── */
function bfWorkerBody() {
  function fmtv(v) { return (v === Infinity || v === null) ? '\u221e' : String(v); }
  self.onmessage = function (ev) {
    var msg = ev.data, edges = msg.edges, verts = msg.verts, passes = msg.passes, source = msg.source;
    var dist = {}, pred = {};
    for (var i = 0; i < verts.length; i++) dist[verts[i]] = (verts[i] === source) ? 0 : Infinity;
    var frames = [], ops = 0, MAXOPS = 200000, MAXF = 1200;
    var pass = 0, edgeIdx = -1, impPass = 0, curEdge = null;
    function snap() {
      var d = {}, p = {}, k;
      for (k in dist) d[k] = (dist[k] === Infinity ? null : dist[k]);
      for (k in pred) p[k] = pred[k];
      return { dist: d, pred: p };
    }
    function push(kind, indices, message, tent) {
      if (frames.length >= MAXF) throw new Error('__CAP__frame cap (' + MAXF + ') hit — is relax() writing in a loop?');
      frames.push({ kind: kind, state: snap(), indices: indices || [], message: message || '',
        tent: (tent === undefined ? null : tent), pass: pass, imp: impPass, edgeIdx: edgeIdx,
        cur: curEdge ? [curEdge.u, curEdge.v] : null });
    }
    function guard() { if (++ops > MAXOPS) throw new Error('__CAP__operation cap hit — too many API calls'); }
    function chk(v) { v = String(v); if (verts.indexOf(v) < 0) throw new Error('unknown vertex "' + v + '"'); return v; }
    var API = {
      d: function (v) { guard(); return dist[chk(v)]; },
      w: function (u, v) { guard(); u = chk(u); v = chk(v);
        for (var i = 0; i < edges.length; i++) if (edges[i].u === u && edges[i].v === v) return edges[i].w;
        return Infinity; },
      setD: function (v, val) { guard(); v = chk(v);
        if (typeof val !== 'number' || isNaN(val)) throw new Error('setD(' + v + ', \u2026) expects a number');
        var old = dist[v]; if (val < old) impPass++;
        dist[v] = val;
        push('update', [v], 'set d[' + v + '] = ' + fmtv(val) + '  (was ' + fmtv(old) + ')'); },
      setPred: function (v, u) { guard(); v = chk(v); u = chk(u); pred[v] = u;
        push('pred', [u, v], '\u03c0[' + v + '] = ' + u + '   tree edge ' + u + '\u2192' + v); },
      note: function (txt) { guard(); if (frames.length) frames[frames.length - 1].message += '  \u00b7  ' + String(txt); }
    };
    if (Object.freeze) Object.freeze(API);
    var relax = null;
    try {
      var factory = new Function('d', 'setD', 'setPred', 'w', 'note',
        '"use strict";\n' + msg.code + '\n;return (typeof relax === "function") ? relax : null;');
      relax = factory(API.d, API.setD, API.setPred, API.w, API.note);
    } catch (err) {
      self.postMessage({ ok: false, frames: [], error: 'Syntax error: ' + (err && err.message ? err.message : err) });
      return;
    }
    if (!relax) {
      self.postMessage({ ok: false, frames: [], error: 'No function named relax(u, v, w) was defined \u2014 the entry point must be called relax.' });
      return;
    }
    try {
      push('init', [], 'Initialization: d[' + source + '] = 0, every other estimate = \u221e');
      for (pass = 1; pass <= passes; pass++) {
        impPass = 0;
        for (edgeIdx = 0; edgeIdx < edges.length; edgeIdx++) {
          var e = edges[edgeIdx]; curEdge = e;
          var du = dist[e.u], sum = du + e.w;
          push('test', [e.u, e.v], 'Pass ' + pass + ': test (' + e.u + ',' + e.v + ') w=' + e.w +
            ' \u2192 d[' + e.u + ']+w = ' + fmtv(du === Infinity ? Infinity : sum) +
            '  vs  d[' + e.v + '] = ' + fmtv(dist[e.v]), (du === Infinity ? null : sum));
          relax(e.u, e.v, e.w);
        }
        curEdge = null; edgeIdx = -1;
        push('passend', [], 'End of pass ' + pass + ' \u2014 distances improved this pass: ' + impPass);
      }
      self.postMessage({ ok: true, frames: frames, final: snap() });
    } catch (err) {
      var m = String(err && err.message ? err.message : err);
      if (m.indexOf('__CAP__') === 0) m = m.slice(7);
      curEdge = null;
      try { push('error', [], 'Error: ' + m); } catch (e2) {}
      self.postMessage({ ok: false, frames: frames, error: m });
    }
  };
}

/* ─────────── run / replay ─────────── */
var frames = [], idx = 0, badEdges = [], badVerts = [], worker = null, playTimer = null, fps = 6;

function parseOrder(src) {
  var re = /\(\s*([A-Za-z_]\w*)\s*,\s*([A-Za-z_]\w*)\s*,\s*(-?\d+(?:\.\d+)?)\s*\)/g, m, out = [];
  while ((m = re.exec(src))) {
    if (VERTS.indexOf(m[1]) < 0 || VERTS.indexOf(m[2]) < 0)
      throw new Error('unknown vertex in (' + m[1] + ',' + m[2] + ') — use s, t, x, y, z');
    out.push({ u: m[1], v: m[2], w: parseFloat(m[3]) });
  }
  if (!out.length) throw new Error('no edges parsed — expected entries like (t,x,5)');
  return out;
}
function setStatus(kind, txt) {
  var el = document.getElementById('runStatus');
  el.textContent = txt;
  el.style.color = (kind === 'ok') ? '#177a2e' : (kind === 'err') ? '#c00000' : (kind === 'warn') ? '#a35400' : '#555';
}
function loadCode(which) {
  document.getElementById('relaxEditorCode').value = CODES[which];
  ['sample', 'buggy', 'starter'].forEach(function (k) {
    var b = document.getElementById('tabBtn_' + k); if (b) b.className = (k === which) ? 'active' : '';
  });
}
function trigger_run() {
  stopPlay();
  var edges;
  try { edges = parseOrder(document.getElementById('relaxEditorInput').value); }
  catch (e) { setStatus('err', '\u2716 Edge list: ' + e.message); return; }
  orderEdges = edges; rebuildOrderList(edges);
  var code = document.getElementById('relaxEditorCode').value;
  setStatus('run', 'running\u2026');
  var btn = document.getElementById('runBtn'); btn.disabled = true;
  if (worker) { worker.terminate(); worker = null; }
  var url = URL.createObjectURL(new Blob(['(' + bfWorkerBody.toString() + ')()'], { type: 'text/javascript' }));
  var done = false;
  function cleanup() { if (worker) { worker.terminate(); worker = null; } URL.revokeObjectURL(url); btn.disabled = false; }
  worker = new Worker(url);
  var timer = setTimeout(function () {
    if (done) return; done = true; cleanup();
    finishRun({ ok: false, frames: [], error: 'Timed out after 1.5 s \u2014 infinite loop in relax()?' });
  }, 1500);
  worker.onmessage = function (ev) { if (done) return; done = true; clearTimeout(timer); cleanup(); finishRun(ev.data); };
  worker.onerror = function (ev) {
    if (done) return; done = true; clearTimeout(timer); cleanup();
    finishRun({ ok: false, frames: [], error: 'Worker error: ' + (ev.message || 'unknown') });
  };
  worker.postMessage({ code: code, edges: edges, verts: VERTS, passes: 4, source: 's' });
}
function checkRun(final) {
  badEdges = []; badVerts = [];
  var dist = final.dist, pred = final.pred || {};
  orderEdges.forEach(function (e) {
    var du = dist[e.u], dv = dist[e.v];
    if (du === null) return;
    if (dv === null || dv > du + e.w + 1e-9) badEdges.push(e.u + '>' + e.v);
  });
  var exp = { s: 0, t: 2, x: 4, y: 7, z: -2 };
  VERTS.forEach(function (k) { if (dist[k] !== exp[k]) badVerts.push(k); });
  var treeOK = pred.y === 's' && pred.x === 'y' && pred.t === 'x' && pred.z === 't';
  if (!badEdges.length && !badVerts.length && treeOK)
    return { ok: true, text: '\u2714 correct \u2014 d = (s 0, t 2, x 4, y 7, z \u22122), tree s\u2192y\u2192x\u2192t\u2192z' };
  var bits = [];
  if (badVerts.length) bits.push('wrong d at ' + badVerts.join(', '));
  if (badEdges.length) bits.push(badEdges.length + ' edge(s) still violate d[v] \u2264 d[u]+w (dashed red)');
  if (!treeOK && !badVerts.length) bits.push('predecessor tree is not s\u2192y\u2192x\u2192t\u2192z');
  return { ok: false, text: '\u2716 wrong answer \u2014 ' + bits.join('; ') };
}
function finishRun(res) {
  frames = res.frames || [];
  badEdges = []; badVerts = [];
  if (res.ok) { var c = checkRun(res.final); setStatus(c.ok ? 'ok' : 'warn', c.text); }
  else { setStatus('err', '\u2716 ' + (res.error || 'error')); }
  if (frames.length) { mode = 'replay'; setActiveSnap(null); showFrame(frames.length - 1); }
  else { document.getElementById('frameCounter').textContent = '0 of 0'; }
}
function showFrame(i) {
  if (!frames.length) return;
  idx = Math.max(0, Math.min(frames.length - 1, i));
  var f = frames[idx];
  var cap = f.pass ? ('pass ' + f.pass + ' of 4') : (f.kind === 'error' ? 'run stopped' : 'initialization');
  var isLast = (idx === frames.length - 1);
  renderView({
    dist: f.state.dist, pred: f.state.pred, caption: cap, capSize: 20, imp: f.imp,
    note: f.message,
    cur: f.cur, tent: (f.kind === 'test' ? f.tent : null),
    upd: (f.kind === 'update' ? f.indices[0] : null),
    edgeIdx: f.edgeIdx, bad: isLast ? badEdges : [], badVerts: isLast ? badVerts : []
  });
  document.getElementById('frameCounter').textContent = (idx + 1) + ' of ' + frames.length;
  document.getElementById('frameCaption').textContent = f.message;
  var lines = [];
  for (var k = Math.max(0, idx - 7); k <= idx; k++) lines.push((k + 1) + '. ' + frames[k].message);
  document.getElementById('runLog').textContent = lines.join('\n');
}
function playFirst() { stopPlay(); if (frames.length) { mode = 'replay'; setActiveSnap(null); showFrame(0); } }
function playPrev() { stopPlay(); if (frames.length) { mode = 'replay'; setActiveSnap(null); showFrame(idx - 1); } }
function playNext() { stopPlay(); if (frames.length) { mode = 'replay'; setActiveSnap(null); showFrame(idx + 1); } }
function stopPlay() {
  if (playTimer) { clearInterval(playTimer); playTimer = null; }
  var b = document.getElementById('playBtn'); if (b) { b.textContent = '\u25b6'; b.className = ''; }
}
function playToggle() {
  if (playTimer) { stopPlay(); return; }
  if (!frames.length) { setStatus('warn', 'Run the code first, then replay.'); return; }
  mode = 'replay'; setActiveSnap(null);
  if (idx >= frames.length - 1) showFrame(0);
  var b = document.getElementById('playBtn'); b.textContent = '\u2759\u2759'; b.className = 'active';
  playTimer = setInterval(function () {
    if (idx >= frames.length - 1) { stopPlay(); return; }
    showFrame(idx + 1);
  }, Math.round(1000 / fps));
}
function update_speed(v) { fps = v; if (playTimer) { stopPlay(); playToggle(); } }

/* ─────────── demo step player ─────────── */
var STEPS = [
  { title: '(a) Initialization', snap: 'init', code: 'sample',
    narration: 'Every estimate starts at \u221e except the source s, which is 0. All ten edges are thin and unshaded \u2014 no predecessor links exist yet.' },
  { title: '(b) After pass 1', snap: 'pass1', code: 'sample',
    narration: 'Only edges leaving s can improve anything on the first sweep: d[t] becomes 6 and d[y] becomes 7. Paths of one edge are now correct.' },
  { title: '(c) After pass 2', snap: 'pass2', code: 'sample',
    narration: 'With t and y settled, relaxing y\u2192x (\u22123) gives d[x] = 4 and t\u2192z (\u22124) gives d[z] = 2. Two-edge paths are correct, and the tree rewires to s\u2192y\u2192x.' },
  { title: '(d) After pass 3', snap: 'pass3', code: 'sample',
    narration: 'The negative edge x\u2192t pays off: s\u2192y\u2192x\u2192t costs 2, beating the direct edge of weight 6. d[t] drops 6\u21922 and t\u2019s parent switches from s to x.' },
  { title: '(e) After pass 4 \u2014 converged', snap: 'pass4', code: 'sample',
    narration: 'The improved d[t] = 2 finally flows through t\u2192z, pushing d[z] to \u22122. A fifth pass would change nothing: every edge satisfies d[v] \u2264 d[u] + w.' },
  { title: 'Break the relaxation', snap: 'pass4', code: 'buggy', run: true,
    narration: 'The buggy version drops the edge weight from the comparison, and it has just been run for you. Read the status line and scrub the frames: the very first setD that ignores w shows why the whole algorithm lives in that one inequality. Edit the code and re-run to compare.' }
];
var stepI = 0;
function applyStep(i) {
  stepI = Math.max(0, Math.min(STEPS.length - 1, i));
  var st = STEPS[stepI];
  document.getElementById('demoNarration').textContent = st.narration;
  document.getElementById('stepLabel').textContent = (stepI + 1) + '/' + STEPS.length + '  ' + st.title;
  var cb = document.getElementById('showTreeInput');
  cb.checked = true; treeOn = true;
  loadCode(st.code);
  setSnapshot(st.snap);
  if (st.run) trigger_run();
}
function nextStep() { applyStep(stepI + 1); }
function prevStep() { applyStep(stepI - 1); }

/* ─────────── boot ─────────── */
rebuildOrderList(orderEdges);
loadCode('sample');
applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Bellman-Ford finds shortest paths by relaxing every edge once per pass, |V|−1 times, letting improvements — including those caused by negative-weight edges — propagate one hop further with each pass.
KEY INSIGHT (what students should walk away understanding): One dumb rule — 'if going through u is cheaper, take it' — applied blindly to every edge, |V|−1 times, is enough to find all shortest paths: each pass lets a correct answer travel exactly one more edge outward, which is why a negative edge discovered late can still fix a vertex on a later pass.
DEMO STEPS: 6 guided steps — implement the step player in #ui

FULL BLUEPRINT:
{
  "concept": "Bellman-Ford finds shortest paths by relaxing every edge once per pass, |V|−1 times, letting improvements — including those caused by negative-weight edges — propagate one hop further with each pass.",
  "figureType": "network_diagram",
  "elements": [
    "Five vertex circles (light gray fill, black outline) labeled outside with italic letters: s at far left, t upper center-left, y lower center-left, x upper right, z lower right",
    "Distance estimate d[v] rendered large inside each circle (starts as 0 for s and ∞ for t, x, y, z)",
    "Directed edge s→t labeled 6",
    "Directed edge s→y labeled 7",
    "Directed edge t→x labeled 5 (curved arc over the top)",
    "Directed edge x→t labeled −2 (curved arc returning below the 5-arc)",
    "Directed edge t→y labeled 8 (vertical, t down to y)",
    "Directed edge t→z labeled −4 (diagonal from t down-right to z)",
    "Directed edge y→x labeled −3 (diagonal from y up-right to x)",
    "Directed edge y→z labeled 9 (horizontal, y to z)",
    "Directed edge z→x labeled 7 (vertical, z up to x)",
    "Directed edge z→s labeled 2 (long diagonal from z back to s)",
    "Bold gray highlight stroke drawn underneath the edges currently in the predecessor subgraph (π-tree)",
    "Pass counter / caption text: 'Initialization' or 'Pass k of 4'",
    "Change counter: 'distances improved this pass: n'",
    "Edge-order list panel showing the fixed relaxation order: (t,x) (t,y) (t,z) (x,t) (y,x) (y,z) (z,x) (z,s) (s,t) (s,y)",
    "Current-edge marker: the edge under consideration flashes in a contrasting color with its tentative sum d[u]+w shown",
    "Final answer annotation for panel (e): d = {s:0, t:2, x:4, y:7, z:−2}"
  ],
  "interactions": [
    {
      "id": "relaxEditor",
      "type": "code_editor",
      "teaches": "That the entire algorithm is one three-line test — 'is going through u cheaper?' — and that the order and number of times you apply it is what makes shortest paths converge; a wrong or missing comparison visibly stalls or corrupts the propagation.",
      "label": "Implement the relaxation step",
      "entry_point": "relax(u, v, w)",
      "api": [
        {
          "op": "d(v)",
          "does": "current shortest-path estimate of vertex v (Infinity if not yet reached)"
        },
        {
          "op": "setD(v, value)",
          "does": "write a new estimate into vertex v's circle — the ONLY way to change a distance"
        },
        {
          "op": "setPred(v, u)",
          "does": "record u as v's predecessor; the shaded gray tree is drawn from these links"
        },
        {
          "op": "w(u, v)",
          "does": "weight of edge u→v (also handed to you as the third argument)"
        },
        {
          "op": "note(text)",
          "does": "attach your own caption to the current frame, e.g. note('improved x via y')"
        }
      ],
      "frame": "the whole 5-vertex graph with all five d-values, the edge (u,v) currently being tested drawn in the highlight color with its tentative sum d[u]+w, the shaded predecessor tree so far, the pass number, and the running count of improvements",
      "input": {
        "label": "Edge relaxation order (fixed, 4 passes)",
        "default": "(t,x,5) (t,y,8) (t,z,-4) (x,t,-2) (y,x,-3) (y,z,9) (z,x,7) (z,s,2) (s,t,6) (s,y,7)"
      },
      "sample_code": "// Called once per edge, ten edges per pass, four passes.\n// dist starts at s = 0, everything else Infinity.\nfunction relax(u, v, w) {\n  if (d(u) + w < d(v)) {\n    setD(v, d(u) + w);\n    setPred(v, u);\n    note('improved ' + v + ' via ' + u);\n  }\n}",
      "buggy_code": "function relax(u, v, w) {\n  // BUG: compares the endpoints' estimates but forgets the edge weight,\n  // so it copies d(u) into v and ignores the cost of the hop.\n  if (d(u) < d(v)) {\n    setD(v, d(u));\n    setPred(v, u);\n  }\n}",
      "success_check": "After 4 passes every edge (u,v) satisfies d(v) <= d(u) + w(u,v), and the final estimates are s=0, t=2, x=4, y=7, z=-2 with the predecessor tree s→y→x→t→z."
    },
    {
      "id": "passStepper",
      "type": "state",
      "teaches": "That each pass extends correct shortest paths by exactly one more edge, so panels (a)–(e) are snapshots of the same code run five times over the same edge list.",
      "label": "Snapshot",
      "states": [
        "init",
        "pass1",
        "pass2",
        "pass3",
        "pass4"
      ],
      "default": "init"
    },
    {
      "id": "showTree",
      "type": "toggle",
      "teaches": "That the shaded gray edges are not 'edges just relaxed' but the current predecessor subgraph — a tree that gets rewired whenever a better route is found.",
      "label": "Shade predecessor tree",
      "default": true
    }
  ],
  "demo_steps": [
    {
      "title": "(a) Initialization",
      "narration": "Every estimate starts at ∞ except the source s, which is 0. All ten edges are thin and unshaded — no predecessor links exist yet.",
      "state": {
        "passStepper": "init",
        "showTree": true
      }
    },
    {
      "title": "(b) After pass 1",
      "narration": "Only edges leaving s can improve anything on the first sweep: d[t] becomes 6 and d[y] becomes 7. Paths of length one edge are now correct.",
      "state": {
        "passStepper": "pass1",
        "showTree": true
      }
    },
    {
      "title": "(c) After pass 2",
      "narration": "With t and y settled, relaxing y→x (−3) gives d[x] = 4 and t→z (−4) gives d[z] = 2. Two-edge paths are now correct, and the tree rewires to s→y→x.",
      "state": {
        "passStepper": "pass2",
        "showTree": true
      }
    },
    {
      "title": "(d) After pass 3",
      "narration": "The negative edge x→t pays off: going s→y→x→t costs 2, beating the direct edge of weight 6. d[t] drops from 6 to 2 and t's parent switches from s to x.",
      "state": {
        "passStepper": "pass3",
        "showTree": true
      }
    },
    {
      "title": "(e) After pass 4 — converged",
      "narration": "The improved d[t] = 2 finally flows through t→z, pushing d[z] to −2. A fifth pass would change nothing: every edge now satisfies d[v] ≤ d[u] + w.",
      "state": {
        "passStepper": "pass4",
        "showTree": true
      }
    },
